/// A TCP proxy in front of one link. It forwards both ways and counts the bytes forwarded
/// toward the receiver; on the test's word it holds that traffic, releases it, or cuts the
/// link by closing both sockets.
struct Proxy {
    port: u16,
    forwarded: Arc<watch::Sender<usize>>,
    held: Arc<watch::Sender<bool>>,
    cut: Arc<watch::Sender<bool>>,
    task: JoinHandle<()>,
}

impl Proxy {
    async fn new(to: u16) -> Proxy {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = listener.local_addr().unwrap().port();
        let forwarded = Arc::new(watch::Sender::new(0));
        let held = Arc::new(watch::Sender::new(false));
        let cut = Arc::new(watch::Sender::new(false));
        let (c_forwarded, c_held, c_cut) = (forwarded.clone(), held.clone(), cut.clone());
        let task = tokio::spawn(async move {
            let (client, _) = listener.accept().await.unwrap();
            let server = TcpStream::connect(("127.0.0.1", to)).await.unwrap();
            let (mut client_rx, mut client_tx) = client.into_split();
            let (mut server_rx, mut server_tx) = server.into_split();
            let toward_receiver = async move {
                let mut buffer = vec![0; 65_536];
                loop {
                    let n = match client_rx.read(&mut buffer).await {
                        Ok(0) | Err(_) => break,
                        Ok(n) => n,
                    };
                    let _ = c_held.subscribe().wait_for(|held| !held).await;
                    if server_tx.write_all(&buffer[..n]).await.is_err() {
                        break;
                    }
                    c_forwarded.send_modify(|bytes| *bytes += n);
                }
            };
            let toward_sender = async move {
                let _ = tokio::io::copy(&mut server_rx, &mut client_tx).await;
            };
            let mut cut = c_cut.subscribe();
            tokio::select! {
                _ = async { tokio::join!(toward_receiver, toward_sender) } => {}
                _ = cut.wait_for(|cut| *cut) => {}
            }
        });
        Proxy {
            port,
            forwarded,
            held,
            cut,
            task,
        }
    }

    /// The endpoint the sender connects to, with the link's metadata, e.g. `prio=4-5`.
    fn endpoint(&self, metadata: &str) -> EndPoint {
        format!("tcp/127.0.0.1:{}?{metadata}", self.port)
            .parse()
            .unwrap()
    }

    fn hold(&self) {
        self.held.send_replace(true);
    }

    fn release(&self) {
        self.held.send_replace(false);
    }

    #[allow(dead_code)]
    fn cut(&self) {
        self.cut.send_replace(true);
    }

    fn forwarded(&self) -> usize {
        *self.forwarded.borrow()
    }

    async fn forwarded_at_least(&self, bytes: usize) {
        let _ = self
            .forwarded
            .subscribe()
            .wait_for(|forwarded| *forwarded >= bytes)
            .await;
    }
}

impl Drop for Proxy {
    fn drop(&mut self) {
        self.task.abort();
    }
}

/// What the receiver heard: each Push's index and payload length in arrival order, and
/// whether the transport closed.
#[derive(Debug)]
struct Log {
    received: Mutex<Vec<(u32, usize)>>,
    count: watch::Sender<usize>,
    closed: watch::Sender<bool>,
}

impl Log {
    fn new() -> Arc<Log> {
        Arc::new(Log {
            received: Mutex::new(vec![]),
            count: watch::Sender::new(0),
            closed: watch::Sender::new(false),
        })
    }

    fn indices(&self) -> Vec<u32> {
        self.received
            .lock()
            .unwrap()
            .iter()
            .map(|(index, _)| *index)
            .collect()
    }

    fn len_of(&self, index: u32) -> Option<usize> {
        self.received
            .lock()
            .unwrap()
            .iter()
            .find(|(i, _)| *i == index)
            .map(|(_, len)| *len)
    }

    async fn until_received(&self, index: u32) {
        let _ = self
            .count
            .subscribe()
            .wait_for(|_| self.indices().contains(&index))
            .await;
    }

    async fn until_count(&self, count: usize) {
        let _ = self.count.subscribe().wait_for(|n| *n >= count).await;
    }

    async fn until_closed(&self) {
        let _ = self.closed.subscribe().wait_for(|closed| *closed).await;
    }
}

