struct ReceiverPeer(Arc<Log>);

impl TransportPeerEventHandler for ReceiverPeer {
    fn handle_message(&self, message: NetworkMessageMut) -> ZResult<()> {
        if let NetworkBodyMut::Push(push) = message.body {
            if let PushBody::Put(put) = &push.payload {
                let bytes = put.payload.contiguous();
                let index = u32::from_be_bytes(bytes[..4].try_into().unwrap());
                self.0
                    .received
                    .lock()
                    .unwrap()
                    .push((index, put.payload.len()));
                self.0.count.send_modify(|count| *count += 1);
            }
        }
        Ok(())
    }

    fn new_link(&self, _link: Link) {}
    fn del_link(&self, _link: Link) {}

    fn closed(&self) {
        self.0.closed.send_replace(true);
    }

    fn as_any(&self) -> &dyn Any {
        self
    }
}

