/// A receiver with the given ordering, listening on a local port, and a sender; both admit
/// two links per transport.
struct Pair {
    receiver: TransportManager,
    sender: TransportManager,
    log: Arc<Log>,
    port: u16,
}

impl Pair {
    async fn new(ordering: UnicastOrdering) -> Pair {
        let log = Log::new();
        let receiver = TransportManager::builder()
            .whatami(WhatAmI::Router)
            .zid(ZenohIdProto::try_from([2]).unwrap())
            .unicast(
                TransportManager::config_unicast()
                    .max_links(2)
                    .ordering(ordering),
            )
            .build_test(Arc::new(ReceiverHandler(log.clone())))
            .unwrap();
        let port = get_free_tcp_port();
        let listener: EndPoint = format!("tcp/127.0.0.1:{port}").parse().unwrap();
        let _ = ztimeout!(receiver.add_listener(listener)).unwrap();
        let sender = TransportManager::builder()
            .whatami(WhatAmI::Router)
            .zid(ZenohIdProto::try_from([1]).unwrap())
            .unicast(TransportManager::config_unicast().max_links(2))
            .build_test(Arc::new(SenderHandler))
            .unwrap();
        Pair {
            receiver,
            sender,
            log,
            port,
        }
    }

    /// Opens a link to the receiver through `endpoint`: the transport's first, or another.
    async fn open(&self, endpoint: EndPoint) -> TransportUnicast {
        ztimeout!(self.sender.open_transport_unicast(endpoint)).unwrap()
    }

    async fn close(self) {
        ztimeout!(self.sender.close());
        ztimeout!(self.receiver.close());
    }
}

/// A Push whose payload starts with `index`, `size` bytes long.
fn message(
    index: u32,
    size: usize,
    priority: Priority,
    reliability: Reliability,
) -> NetworkMessage {
    let mut payload = vec![0; size.max(4)];
    payload[..4].copy_from_slice(&index.to_be_bytes());
    let mut message = NetworkMessage::from(Push {
        wire_expr: "test".into(),
        ext_qos: QoSType::new(priority, CongestionControl::Block, false),
        ..Push::from(payload)
    });
    message.reliability = reliability;
    message
}

fn send(transport: &TransportUnicast, message: NetworkMessage) {
    let mut message = message;
    assert!(transport.schedule(message.as_mut()).unwrap());
}

const SMALL: usize = 8;
const BIG: usize = 300_000;

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn frames_of_one_priority_read_across_two_links_out_of_order_are_delivered_in_order() {
    zenoh_util::init_log_from_env_or("error");
    let pair = Pair::new(ORDERING).await;
    let (a, b) = (Proxy::new(pair.port).await, Proxy::new(pair.port).await);

    // Link A carries priorities 4-5; Control frames take it as the partial match.
    let transport = pair.open(a.endpoint("prio=4-5")).await;
    a.hold();
    for index in 0..50 {
        send(
            &transport,
            message(index, SMALL, Priority::Control, Reliability::Reliable),
        );
    }
    // Link B carries priorities 0-1; Control frames take it from now on.
    pair.open(b.endpoint("prio=0-1")).await;
    let baseline = b.forwarded();
    for index in 50..100 {
        send(
            &transport,
            message(index, SMALL, Priority::Control, Reliability::Reliable),
        );
    }
    ztimeout!(b.forwarded_at_least(baseline + 50 * SMALL));
    a.release();
    send(
        &transport,
        message(100, SMALL, Priority::Control, Reliability::Reliable),
    );
    ztimeout!(pair.log.until_received(100));

    assert_eq!(pair.log.indices(), (0..=100).collect::<Vec<_>>());
    pair.close().await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn with_ordering_a_message_bigger_than_a_batch_then_small_ones_arrive_whole_and_in_order() {
    zenoh_util::init_log_from_env_or("error");
    let pair = Pair::new(ORDERING).await;
    let endpoint: EndPoint = format!("tcp/127.0.0.1:{}", pair.port).parse().unwrap();
    let transport = pair.open(endpoint).await;

    send(
        &transport,
        message(0, BIG, Priority::Data, Reliability::Reliable),
    );
    for index in 1..=10 {
        send(
            &transport,
            message(index, SMALL, Priority::Data, Reliability::Reliable),
        );
    }
    ztimeout!(pair.log.until_received(10));

    assert_eq!(pair.log.indices(), (0..=10).collect::<Vec<_>>());
    assert_eq!(pair.log.len_of(0), Some(BIG));
    pair.close().await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn best_effort_frames_are_never_held() {
    zenoh_util::init_log_from_env_or("error");
    let pair = Pair::new(ORDERING).await;
    let (a, b) = (Proxy::new(pair.port).await, Proxy::new(pair.port).await);

    // Link A is reliable and carries priorities 4-5: best-effort Control frames take it while
    // no link matches both.
    let transport = pair.open(a.endpoint("prio=4-5")).await;
    a.hold();
    for index in 0..50 {
        send(
            &transport,
            message(index, SMALL, Priority::Control, Reliability::BestEffort),
        );
    }
    // Link B is best effort and carries priorities 0-1: it matches both from now on.
    pair.open(b.endpoint("prio=0-1;rel=0")).await;
    for index in 50..100 {
        send(
            &transport,
            message(index, SMALL, Priority::Control, Reliability::BestEffort),
        );
    }
    // B's frames are delivered while A is still held: nothing waits for A's.
    ztimeout!(pair.log.until_count(50));
    a.release();
    send(
        &transport,
        message(100, SMALL, Priority::Control, Reliability::BestEffort),
    );
    ztimeout!(pair.log.until_received(100));

    // A's frames arrived after B's and were dropped as old.
    assert_eq!(pair.log.indices(), (50..=100).collect::<Vec<_>>());
    pair.close().await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_fragmented_message_held_behind_a_gap_is_delivered_whole() {
    zenoh_util::init_log_from_env_or("error");
    let pair = Pair::new(ORDERING).await;
    let (a, b) = (Proxy::new(pair.port).await, Proxy::new(pair.port).await);

    let transport = pair.open(a.endpoint("prio=4-5")).await;
    a.hold();
    for index in 0..5 {
        send(
            &transport,
            message(index, SMALL, Priority::Control, Reliability::Reliable),
        );
    }
    pair.open(b.endpoint("prio=0-1")).await;
    let baseline = b.forwarded();
    send(
        &transport,
        message(5, BIG, Priority::Control, Reliability::Reliable),
    );
    send(
        &transport,
        message(6, SMALL, Priority::Control, Reliability::Reliable),
    );
    ztimeout!(b.forwarded_at_least(baseline + BIG + SMALL));
    a.release();
    ztimeout!(pair.log.until_received(6));

    assert_eq!(pair.log.indices(), (0..=6).collect::<Vec<_>>());
    assert_eq!(pair.log.len_of(5), Some(BIG));
    pair.close().await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_gap_held_past_its_bound_closes_the_transport() {
    zenoh_util::init_log_from_env_or("error");
    let pair = Pair::new(UnicastOrdering {
        max_hold: Duration::from_millis(500),
        ..ORDERING
    })
    .await;
    let (a, b) = (Proxy::new(pair.port).await, Proxy::new(pair.port).await);

    let transport = pair.open(a.endpoint("prio=4-5")).await;
    a.hold();
    send(
        &transport,
        message(0, SMALL, Priority::Control, Reliability::Reliable),
    );
    pair.open(b.endpoint("prio=0-1")).await;
    send(
        &transport,
        message(1, SMALL, Priority::Control, Reliability::Reliable),
    );

    tokio::time::timeout(BOUND_TIMEOUT, pair.log.until_closed())
        .await
        .expect("the transport closed at the hold's time bound");
    assert!(pair.log.indices().is_empty());
    pair.close().await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
